#!/bin/bash
set -euo pipefail
export LIBGL_ALWAYS_SOFTWARE=1 SDL_VIDEODRIVER=x11 XDG_RUNTIME_DIR=/tmp TMPDIR=/tmp LP_NUM_THREADS=4
qemu-img create -f qcow2 -F raw -b /vm/root.img /tmp/tracer-overlay.qcow2
exec timeout --signal=TERM --kill-after=10s 600s xvfb-run -a -s '-screen 0 1080x2424x24 -dpi 100 -nolisten tcp' qemu-system-aarch64 -machine virt,gic-version=3 -cpu max -accel tcg,thread=multi -smp 8 -m 6144 -kernel /workspace/sim/boot/Image -initrd /workspace/sim/boot/initramfs-linux.img -append 'console=ttyAMA0 root=/dev/vda rw rootwait panic=10 systemd.mask=sshd.service systemd.mask=serial-getty@ttyAMA0.service systemd.mask=systemd-networkd-wait-online.service' -drive file=/tmp/tracer-overlay.qcow2,if=none,id=root,format=qcow2 -device virtio-blk-pci,drive=root -device virtio-gpu-gl-pci,id=phone-display,xres=1080,yres=2424 -device virtio-keyboard-pci -device virtio-rng-pci -nic none -fsdev local,id=project,path=/workspace,security_model=none,readonly=on -device virtio-9p-pci,fsdev=project,mount_tag=project -fsdev local,id=results,path=/results,security_model=mapped-xattr -device virtio-9p-pci,fsdev=results,mount_tag=results -fsdev local,id=runtime,path=/android-runtime,security_model=none,readonly=on -device virtio-9p-pci,fsdev=runtime,mount_tag=android-runtime -qmp unix:/results/qmp.sock,server=on,wait=off -display sdl,gl=on -serial stdio -monitor none -no-reboot
